-- Two `ON DELETE SET NULL` keys null one row twice, and only the second image enters a
-- partial index over both keys, with an entry over the item limit.
-- @setup
CREATE TABLE p (k text PRIMARY KEY);
INSERT INTO p VALUES ('a');
CREATE TABLE c (pad text, k1 text REFERENCES p ON DELETE SET NULL, k2 text REFERENCES p ON DELETE SET NULL);
CREATE INDEX c_pi ON c (pad) WHERE k1 IS NULL AND k2 IS NULL;
INSERT INTO c VALUES ('', 'a', 'a');
-- @test
-- @expect-error: the fully nulled row enters the partial index oversized
-- @expect-message
-- @profile-lock
DELETE FROM p;
